    case 40: /* CURSOR_NAME */
    case 41: /* CURRENT_USER */
    case 42: /* DATAFILE */
    case 43: /* DECIMAL */
    case 44: /* DEFINITION */
    case 45: /* DELAY_KEY_WRITE */
    case 46: /* DESCRIPTION */
    case 47: /* DETERMINISTIC */
    case 48: /* DIRECTORY */
